bank.push(...[{"id": 40, "category": "說話的藝術", "kind": "古典短句", "quote": "辭，達而已矣！", "source": "孔子（語錄）《論語·衛靈公》", "author": "孔子（語錄）", "work": "論語·衛靈公", "url": "https://zh.wikisource.org/wiki/論語/衛靈公第十五", "insight": "原章談言辭應使意思通達。延伸到日常，清楚比堆砌詞語更重要。", "exercise": "用三句話說明一個想法，請對方重述他聽到的重點。", "application": "把話說清楚，是對聽者的照顧。"}, {"id": 41, "category": "文化底蘊", "kind": "古典短句", "quote": "有教無類。", "source": "孔子（語錄）《論語·衛靈公》", "author": "孔子（語錄）", "work": "論語·衛靈公", "url": "https://zh.wikisource.org/wiki/論語/衛靈公第十五", "insight": "此語強調施教不應以類別區分。今天閱讀它，可以反省自己是否先用背景替人設限。", "exercise": "與背景不同的人交談時，問一個關於其經驗的問題。", "application": "先認識一個人，再形成判斷。"}, {"id": 42, "category": "知識見解", "kind": "古典短句", "quote": "君子不以言舉人，不以人廢言。", "source": "孔子（語錄）《論語·衛靈公》", "author": "孔子（語錄）", "work": "論語·衛靈公", "url": "https://zh.wikisource.org/wiki/論語/衛靈公第十五", "insight": "不只憑言辭推舉一個人，也不因不喜歡某人就丟棄其有道理的話。", "exercise": "找一個你不同意的人，辨認其論點中值得考慮的部分。", "application": "我對這個人的評價，影響了我怎麼聽這句話嗎？"}, {"id": 43, "category": "文字素養", "kind": "古典短句", "quote": "工欲善其事，必先利其器。", "source": "孔子（語錄）《論語·衛靈公》", "author": "孔子（語錄）", "work": "論語·衛靈公", "url": "https://zh.wikisource.org/wiki/論語/衛靈公第十五", "insight": "原章由工匠備器談到為仁所需的交往與學習。用在寫作，可提醒自己先備材料再下筆。", "exercise": "動筆前先列出讀者、目的與三項關鍵資料。", "application": "先準備清楚，再表達清楚。"}, {"id": 44, "category": "好好說話", "kind": "古典短句", "quote": "己所不欲，勿施於人。", "source": "孔子（語錄）《論語·顏淵》", "author": "孔子（語錄）", "work": "論語·顏淵", "url": "https://zh.wikisource.org/wiki/論語/顏淵第十二", "insight": "自己不願承受的，不加諸他人。延伸到對話，也要記得他人的需要未必與自己相同。", "exercise": "給建議前，先問「你希望我提供想法嗎？」。", "application": "尊重既需要換位思考，也需要詢問。"}, {"id": 45, "category": "說話的藝術", "kind": "文學節選", "quote": "人非生而知之者，孰能無惑？", "source": "韓愈《師說》", "author": "韓愈", "work": "師說", "url": "https://zh.wikisource.org/wiki/師說", "insight": "韓愈以人人都有疑惑，說明從師求教的必要。不懂可以是對話的起點。", "exercise": "練習坦白說「這部分我還不懂，可以請你舉例嗎？」。", "application": "容許自己提問，也給別人提問的空間。"}, {"id": 46, "category": "文化底蘊", "kind": "文學節選", "quote": "斯是陋室，惟吾德馨。", "source": "劉禹錫《陋室銘》", "author": "劉禹錫", "work": "陋室銘", "url": "https://zh.wikisource.org/wiki/陋室銘", "insight": "作者借居室表達對自身德行的重視，以「馨」將品格寫成能感知的芬芳。", "exercise": "留意一個比喻：作者如何把無形的品格寫得具體？", "application": "文化素養也在於看見文字背後的價值選擇。"}, {"id": 47, "category": "知識見解", "kind": "文學節選", "quote": "聞道有先後，術業有專攻。", "source": "韓愈《師說》", "author": "韓愈", "work": "師說", "url": "https://zh.wikisource.org/wiki/師說", "insight": "認識道理有先後，學業技藝各有專長；師生不必在所有方面都形成固定高下。", "exercise": "請教一位在某個領域比你熟悉的人，不以年齡判斷。", "application": "在這個問題上，誰擁有更相關的經驗？"}, {"id": 48, "category": "文字素養", "kind": "文學節選", "quote": "清風徐來，水波不興。", "source": "蘇軾《前赤壁賦》", "author": "蘇軾", "work": "前赤壁賦", "url": "https://zh.wikisource.org/wiki/前赤壁賦", "insight": "以風與水的細微動靜寫出赤壁夜遊的寧靜，簡短句子也能建立完整氛圍。", "exercise": "不用「安靜」兩字，寫一句讓人感到安靜的景物描寫。", "application": "具體的感官細節，能替抽象感受找到形狀。"}, {"id": 49, "category": "好好說話", "kind": "文學節選", "quote": "可遠觀而不可褻玩焉。", "source": "周敦頤《愛蓮說》", "author": "周敦頤", "work": "愛蓮說", "url": "https://zh.wikisource.org/wiki/愛蓮說", "insight": "作者藉蓮的形象寄託君子品格。此處描寫蓮值得敬重，並非可以輕慢玩弄之物。", "exercise": "把一次不舒服的互動，改寫成一個清楚而有禮的界線。", "application": "欣賞可以親切，也可以保有分寸。"}, {"id": 50, "category": "說話的藝術", "kind": "古詩", "quote": "海內存知己，天涯若比隣。", "source": "王勃《送杜少府之任蜀州》", "author": "王勃", "work": "送杜少府之任蜀州", "url": "https://zh.wikisource.org/wiki/送杜少府之任蜀州", "insight": "詩人在送別中以知己之情寬慰友人，讓遙遠的路途不只剩下離愁。「隣」同「鄰」。", "exercise": "向遠方朋友傳一句具體的問候，提起你們共同的回憶。", "application": "安慰可以承認離別，也可以提醒彼此仍有連結。"}, {"id": 51, "category": "文化底蘊", "kind": "古詩", "quote": "山重水複疑無路，柳暗花明又一村。", "source": "陸游《遊山西村》", "author": "陸游", "work": "遊山西村", "url": "https://zh.wikisource.org/wiki/遊山西村", "insight": "原詩寫山村行旅中景色的轉折。後人也借它談困境中的轉機；延伸義不代表每個困境都會自行解決。", "exercise": "寫下當下的一個困難，以及你還可以嘗試的一條路。", "application": "保留希望，也為希望安排一個行動。"}, {"id": 52, "category": "知識見解", "kind": "古詩", "quote": "橫看成嶺側成峰，遠近高低各不同。", "source": "蘇軾《題西林壁》", "author": "蘇軾", "work": "題西林壁", "url": "https://zh.wikisource.org/wiki/題西林壁", "insight": "觀看位置不同，廬山呈現不同面貌。詩句提醒我們思考觀察位置與認識的關係。", "exercise": "選一個爭議，分別從兩位當事人的角度描述所見。", "application": "你所站的位置，讓你看見了什麼、漏掉了什麼？"}, {"id": 53, "category": "文字素養", "kind": "古詩", "quote": "欲窮千里目，更上一層樓。", "source": "王之渙（通行署名）《登鸛雀樓》", "author": "王之渙（通行署名）", "work": "登鸛雀樓", "url": "https://zh.wikisource.org/wiki/登鸛雀樓_(王之渙)", "insight": "從登樓的動作寫出視野的開展，讓景物與志意相連。此詩亦有署名朱斌的傳本，來源頁列有說明。", "exercise": "用一個具體動作，寫出你想成長的願望。", "application": "好句子常讓動作與意思一起向前。"}, {"id": 54, "category": "好好說話", "kind": "古詩", "quote": "會當凌絕頂，一覽衆山小。", "source": "杜甫《望嶽》", "author": "杜甫", "work": "望嶽", "url": "https://zh.wikisource.org/wiki/望嶽_(岱宗夫如何)", "insight": "這是登上泰山絕頂的願望，並非已經登頂的記錄。它以登高的想像寫出胸襟與志向。", "exercise": "向別人介紹目標時，分別說明已完成的事與未來的願望。", "application": "有志向，也把事實與期望說清楚。"}, {"id": 55, "category": "說話的藝術", "kind": "原創觀點", "quote": "把結論說清楚，把餘地留給別人。", "insight": "清楚的立場與願意討論的態度，可以同時存在。", "exercise": "提出建議後，補上一句「你看到的情況呢？」。", "source": "拾句編輯室 · 原創"}, {"id": 56, "category": "文化底蘊", "kind": "原創觀點", "quote": "讀典故，是為了多懂一層人情。", "insight": "典故的來由與使用情境，比單純背誦更能幫助理解。", "exercise": "查一個熟悉成語的原始故事，辨認它與現在用法的差異。", "source": "拾句編輯室 · 原創"}, {"id": 57, "category": "知識見解", "kind": "原創觀點", "quote": "見識，是知道自己的經驗從哪裡開始，又在哪裡結束。", "insight": "經驗能提供線索，也需要辨認適用範圍。", "exercise": "把「大家都」改成你實際觀察過的人與情境。", "source": "拾句編輯室 · 原創"}, {"id": 58, "category": "文字素養", "kind": "原創觀點", "quote": "刪去一句捨不得的話，有時整段文字才終於說出重點。", "insight": "句子的美與段落的目的，需要一起考量。", "exercise": "刪去一段文字中與主旨最遠的一句，再讀一次。", "source": "拾句編輯室 · 原創"}, {"id": 59, "category": "好好說話", "kind": "原創觀點", "quote": "安慰之前，先問問：這份難過，需要陪伴，還是需要辦法？", "insight": "先確認對方需要什麼，再決定是否給建議。", "exercise": "試著說「你想先說一說，還是希望我陪你想想辦法？」。", "source": "拾句編輯室 · 原創"}]);
const kinds=['原創觀點','古典短句','文學節選','古詩'];
const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dayNumber=Math.floor(Date.parse(day)/86400000);
function selectDaily(n){return categories.flatMap((c,i)=>kinds.map(kind=>{const pool=bank.filter(q=>q.category===c&&q.kind===kind);return pool[((n%pool.length)+pool.length)%pool.length]}))}
const daily=selectDaily(dayNumber);
let saved=[],read=[],view='today',filter='全部',kindFilter='全部類型';const key='shiju-v1';let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}');saved=Array.isArray(state.saved)?state.saved:[];read=state.day===day&&state.edition===2&&Array.isArray(state.read)?state.read.filter(id=>daily.some(q=>q.id===id)):[]}catch{};
const $=s=>document.querySelector(s);function persist(){try{localStorage.setItem(key,JSON.stringify({saved,read,day,edition:2,practice:$('#practiceText').value}))}catch{toast('無法儲存，請確認瀏覽器允許本機儲存。')}}
$('#practiceText').value=state.practice||'';$('#date').textContent='◷  '+new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'long',day:'numeric',weekday:'long'}).format(new Date());
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2300)}
function toggle(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render()}
function render(){
$('#savedCount').textContent=saved.length;$('#readLabel').textContent=`已讀 ${read.length} / 20 則`;$('#bar').style.width=`${read.length*5}%`;$('#encourage').textContent=read.length===20?'今天的 20 則已讀完。選一句話，帶進生活裡吧。':'不必急著讀完，讓一句話在心裡停留。';
$('#practicePanel').hidden=view!=='practice';$('#cards').hidden=view==='practice';$('#filters').hidden=view==='practice';$('#kindFilters').hidden=view==='practice';$('.search').hidden=view==='practice';
$('#pageLabel').textContent={today:'今日拾句',saved:'我的書籤',practice:'表達練習'}[view];$('#sectionTitle').innerHTML={today:'今日精選 <span>DAILY PICKS</span>',saved:'我的書籤 <span>MY COLLECTION</span>',practice:'讓好句子成為你的話 <span>DAILY PRACTICE</span>'}[view];$('#sectionDesc').textContent=view==='saved'?'收藏讓你停下來的句子，隨時回來重讀。':view==='practice'?'從一句改寫開始，練習更有溫度的表達。':'讀一句好話，長一分見識。';
$('#filters').innerHTML=['全部',...categories].map(c=>`<button class="filter ${c===filter?'active':''}" data-category="${c}">${c}${c==='全部'?' '+(view==='today'?20:saved.length):''}</button>`).join('');
$('#kindFilters').innerHTML=['全部類型',...kinds].map(k=>`<button class="filter ${k===kindFilter?'active':''}" data-kind="${k}" aria-pressed="${k===kindFilter}">${k}</button>`).join('');
const term=$('#search').value.trim();let items=(view==='saved'?bank.filter(q=>saved.includes(q.id)):daily).filter(q=>(filter==='全部'||q.category===filter)&&(kindFilter==='全部類型'||q.kind===kindFilter)&&[q.quote,q.category,q.insight,q.source,q.kind].join('').includes(term));
$('#cards').innerHTML=items.length?items.map(q=>`<article class="card"><div class="card-top"><span class="tag">${q.category} · ${q.kind}</span><button class="bookmark ${saved.includes(q.id)?'saved':''}" data-save="${q.id}" aria-label="${saved.includes(q.id)?'取消收藏':'收藏金句'}" aria-pressed="${saved.includes(q.id)}">${saved.includes(q.id)?'▣':'♧'}</button></div><div class="quote-mark">“</div><h3 class="quote">${q.quote}</h3><div class="source">— ${q.source}</div><div class="card-bottom"><button class="read-detail" data-detail="${q.id}">讀解與練習 ＋</button><span class="read-state ${read.includes(q.id)?'done':''}">${read.includes(q.id)?'✓ 已閱讀':'約 1 分鐘'}</span></div></article>`).join(''):`<div class="empty">${term?'沒有找到符合的句子，試試其他關鍵字。':view==='saved'?'還沒有收藏。點選金句右上角的收藏圖示，留下喜歡的句子。':'此分類還沒有句子。'}</div>`;
}
$('#cards').addEventListener('click',e=>{let save=e.target.closest('[data-save]');if(save){toggle(+save.dataset.save);return}let b=e.target.closest('[data-detail]');if(!b)return;let q=bank[+b.dataset.detail];if(daily.some(x=>x.id===q.id)&&!read.includes(q.id)){read.push(q.id);persist();render()}$('#detailBody').innerHTML=`<span class="tag">${q.category} · ${q.kind}</span><h2>${q.quote}</h2><small class="source">${q.source}</small>${q.url?`<p class="citation"><a href="${q.url}" target="_blank" rel="noopener noreferrer">閱讀原文與出處</a><br><small>公版原文節選；標點與異體字依閱讀需要整理，傳本差異請見來源。</small></p>`:'<p class="citation">拾句原創觀點，非歷史人物引言。</p>'}<h3>拾句讀解 · 現代延伸</h3><p>${q.insight}</p>${q.application?`<h3>帶進生活裡</h3><p>${q.application}</p>`:""}<h3>今天，這樣練習</h3><p>${q.exercise}</p><button class="primary" id="detailSave">${saved.includes(q.id)?'取消收藏':'收藏這句話'}</button>`;$('#detailSave').onclick=()=>{toggle(q.id);$('#detailSave').textContent=saved.includes(q.id)?'取消收藏':'收藏這句話'};$('#detail').showModal()});
$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#kindFilters').onclick=e=>{const b=e.target.closest('[data-kind]');if(b){kindFilter=b.dataset.kind;render()}};$('#filters').onclick=e=>{const b=e.target.closest('[data-category]');if(b){filter=b.dataset.category;render()}};$('#search').oninput=render;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;filter='全部';kindFilter='全部類型';$('#search').value='';document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x===b));render()});$('#savePractice').onclick=()=>{if(!$('#practiceText').value.trim())return toast('先寫下一句你的練習吧。');persist();toast('練習已儲存，讓表達慢慢進步。')};$('#date').onclick=()=>toast('每日依台北時間更新，從句庫輪替精選 20 則。');render();setInterval(()=>{const now=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(now!==day)location.reload()},60000);
